const D = { energy: .6, scale: 1, density: .5, flux: .6, wave: 1, grain: .3, hue: 200, x: .5, y: .5, style: 'textbook', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---------------------------------------------------------------------------
// Ion channels -- a cross-section of a lipid bilayer, two rows of phosphate
// head-beads with the fatty tails between, extracellular fluid above and
// cytoplasm below. Voltage-gated channel proteins are embedded along it; a
// depolarisation wave sweeps across the membrane and, as its front reaches each
// channel, the pore opens and ions pour through down their electrochemical
// gradient -- sodium in, potassium out -- flipping compartments while the rest
// jitter with Brownian motion. Textbook diagram, a grey cryo-EM density, an
// electric neon schematic, or a blueprint.
// ---------------------------------------------------------------------------
const sd = P.seed | 0;
const fr = i => { const s = Math.sin(i * 127.1 + sd * 311.7) * 43758.5453; return s - Math.floor(s); };

if (!S.fb || S.fw !== width || S.fh !== height) { S.fb = createGraphics(width, height); S.fb.pixelDensity(1); S.fw = width; S.fh = height; }
const f = S.fb, u = Math.min(width, height);
const style = P.style;
const memY = height * (0.35 + P.y * 0.3);
const memH = u * 0.14;
const headR = u * 0.017;
const nHead = Math.max(14, Math.floor(width / (headR * 2.1)));
const nChan = Math.max(4, Math.min(10, Math.round(4 + P.density * 6)));

// channel x positions (seed-jittered)
if (!S.chan || S.ckey !== width + sd + nChan) {
  S.ckey = width + sd + nChan; S.chan = [];
  for (let k = 0; k < nChan; k++) S.chan.push({ x: (k + 0.5 + (fr(k * 4.1) - 0.5) * 0.4) / nChan * width, type: k % 3 });
}
// ion pool
const NI = Math.max(60, Math.floor((90 + P.density * 200)));
if (!S.ions || S.ikey !== width + height + sd || S.ions.length !== NI) {
  S.ikey = width + height + sd; S.ions = [];
  S.rng = (sd * 2654435761 + 0x9e3779b9) | 0; if (S.rng === 0) S.rng = 1;
  const rn = () => { let x = S.rng; x ^= x << 13; x |= 0; x ^= x >>> 17; x ^= x << 5; x |= 0; S.rng = x; return (x >>> 0) / 4294967296; };
  for (let k = 0; k < NI; k++) {
    const above = rn() < 0.5;
    S.ions.push({ x: rn() * width, y: above ? rn() * (memY - memH * 0.6) : memY + memH * 0.6 + rn() * (height - memY - memH * 0.6), t: (rn() * 3) | 0, comp: above ? 0 : 1, cx: 0, cross: 0 });
  }
}
const rn = () => { let x = S.rng; x ^= x << 13; x |= 0; x ^= x >>> 17; x ^= x << 5; x |= 0; S.rng = x; return (x >>> 0) / 4294967296; };

// depolarisation wave front sweeps across (wraps) -- smooth travelling gradient, never a flash
const front = ((K.t * (0.10 + P.wave * 0.16)) % 1.4 - 0.2) * width;
function openness(x) { const d = (x - front) / (u * 0.08); return Math.exp(-d * d); }

// ---- draw ----
f.push(); f.colorMode(HSB, 360, 100, 100, 100); f.clear();
const neon = style === 'neon', cryo = style === 'cryoem', blue = style === 'blueprint';
const hb = P.hue;
// extracellular (top) + cytoplasm (bottom) as flat tinted bands with a moving potential wash
f.noStroke();
if (cryo) { f.background(0, 0, 8); } else if (blue) { f.background(215, 60, 12); } else { f.background(hb, neon ? 55 : 34, neon ? 8 : 14); }
// moving depolarisation wash across the membrane region (broad area element)
f.push(); f.blendMode(cryo ? BLEND : ADD);
for (let x = 0; x < width; x += Math.max(3, u * 0.01)) {
  const op = openness(x);
  if (op < 0.02) continue;
  f.fill(cryo ? 0 : (hb + 40), cryo ? 0 : 70, cryo ? 40 : 100, op * (12 + P.energy * 22));
  f.rect(x, memY - memH * 2.2, u * 0.012 + 2, memH * 4.4);
}
f.pop();

// tails region (membrane interior)
f.noStroke();
f.fill(cryo ? 0 : 45, cryo ? 0 : 18, cryo ? 22 : 20, 100);
f.rect(0, memY - memH * 0.5, width, memH);
// phosphate head rows
for (let s = -1; s <= 1; s += 2) {
  const hy = memY + s * memH * 0.5;
  for (let k = 0; k < nHead; k++) {
    const hx = (k + 0.5) / nHead * width + Math.sin(k * 0.7 + K.t * 0.3 + s) * headR * 0.15;
    if (cryo) { f.fill(0, 0, 55 + fr(k) * 20); } else if (blue) { f.fill(205, 40, 70); } else if (neon) { f.fill(hb, 80, 90); } else { f.fill(hb + 8, 55, 78); }
    f.noStroke(); f.circle(hx, hy, headR * 1.7);
    // tail
    f.stroke(cryo ? 0 : 45, cryo ? 0 : 20, cryo ? 32 : 40, 60); f.strokeWeight(headR * 0.28);
    f.line(hx, hy, hx + Math.sin(k * 1.3) * headR * 0.3, memY);
    f.noStroke();
  }
}

// channel proteins (two lobes + a pore that widens as the wave opens it)
for (let c = 0; c < S.chan.length; c++) {
  const ch = S.chan[c]; const op = openness(ch.x);
  const bw = headR * 3.4, bh = memH * 1.7;
  const col = cryo ? [0, 0, 60] : (blue ? [205, 45, 78] : (neon ? [[52, 90, 100], [285, 80, 100], [140, 85, 100]][ch.type] : [[35, 28, 82], [275, 34, 74], [150, 30, 76]][ch.type]));
  f.noStroke();
  for (let s = -1; s <= 1; s += 2) {
    f.fill(col[0], col[1], col[2], cryo ? 100 : 88);
    f.ellipse(ch.x - s * bw * 0.28, memY, bw * 0.55, bh);
  }
  // pore highlight when open
  const pore = headR * (0.4 + op * 1.5);
  f.fill(cryo ? 0 : col[0], cryo ? 0 : 30, cryo ? 12 + op * 40 : 20 + op * 70, 90);
  f.rect(ch.x - pore * 0.5, memY - bh * 0.5, pore, bh, pore * 0.5);
  if (neon && op > 0.1) { f.drawingContext.shadowBlur = 16 * op; f.drawingContext.shadowColor = 'rgba(120,200,255,0.8)'; f.fill(190, 60, 100, 40 * op); f.rect(ch.x - pore * 0.5, memY - bh * 0.5, pore, bh, pore * 0.5); f.drawingContext.shadowBlur = 0; }
}

// ---- ions: Brownian jitter + flux through open pores ----
const step = u * 0.004 * (0.6 + P.flux);
const iontypes = cryo ? [[0, 0, 92], [0, 0, 78], [0, 0, 85]] : (blue ? [[45, 80, 95], [280, 60, 92], [150, 70, 92]] : [[50, 95, 100], [285, 75, 98], [150, 80, 96]]);
for (let k = 0; k < S.ions.length; k++) {
  const io = S.ions[k];
  io.x += (rn() - 0.5) * step * 2; io.y += (rn() - 0.5) * step * 1.6;
  if (io.x < 0) io.x += width; if (io.x >= width) io.x -= width;
  // find nearest channel; if open and aligned, drift through the pore
  let through = false;
  for (let c = 0; c < S.chan.length; c++) {
    const ch = S.chan[c]; const op = openness(ch.x);
    if (op > 0.35 && Math.abs(io.x - ch.x) < headR * 1.2) {
      const dir = ch.type === 0 ? 1 : -1;   // Na in (down), others out (up)
      io.y += dir * step * 2.2 * op;
      io.x += (ch.x - io.x) * 0.15;
      through = true;
      if (io.comp === 0 && io.y > memY + memH * 0.6) io.comp = 1;
      if (io.comp === 1 && io.y < memY - memH * 0.6) io.comp = 0;
    }
  }
  // bounce off the membrane if not crossing
  if (!through) {
    if (io.comp === 0 && io.y > memY - memH * 0.6) io.y = memY - memH * 0.6 - (rn()) * step;
    if (io.comp === 1 && io.y < memY + memH * 0.6) io.y = memY + memH * 0.6 + (rn()) * step;
  }
  if (io.y < 0) io.y = 0; if (io.y > height) io.y = height;
  const col = iontypes[io.t];
  if (neon || style === 'textbook') { f.drawingContext.shadowBlur = neon ? 8 : 4; f.drawingContext.shadowColor = 'rgba(255,255,255,0.5)'; }
  f.noStroke(); f.fill(col[0], col[1], col[2], 92); f.circle(io.x, io.y, headR * 0.7);
  f.drawingContext.shadowBlur = 0;
}
// membrane potential label line (subtle) + grain
if (P.grain > 0.02) { f.noStroke(); for (let k = 0; k < 70 * P.grain; k++) { f.fill(0, 0, cryo ? 100 : 0, P.grain * 9); f.circle(fr(k * 1.7 + (K.t * 0.5 | 0)) * width, fr(k * 3.1 + (K.t * 0.5 | 0) + 4) * height, u * 0.005); } }
f.pop();

const mag = Math.max(1, P.scale);
const sw = width / mag, sh = height / mag;
const sx = (width - sw) * Math.min(1, Math.max(0, P.x)), sy = (height - sh) * Math.min(1, Math.max(0, P.y));
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(f, 0, 0, width, height, sx, sy, sw, sh);
pop();
blendMode(BLEND);
drawingContext.shadowBlur = 0;
